function load(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v)}catch{return d}}
function save(k,v){localStorage.setItem(k,JSON.stringify(v))}
function el(id){return document.getElementById(id)}
function m12(n){return((n%12)+12)%12}
function uniq(a){return[...new Set(a)]}
function nn(pc,p="sharp"){return(p==="flat"?NF:NS)[m12(pc)]}
function notePc(name){if(!name)return null;let s=name.trim().toUpperCase().replace("♯","#").replace("♭","B");const map={C:0,"C#":1,DB:1,D:2,"D#":3,EB:3,E:4,F:5,"F#":6,GB:6,G:7,"G#":8,AB:8,A:9,"A#":10,BB:10,B:11};return Object.prototype.hasOwnProperty.call(map,s)?map[s]:null}
function noteLabel(pc,prefer="sharp"){return nn(pc,prefer)}
function pcsFor(rootPc,def){return uniq(def.intervals.map(i=>m12(rootPc+i)))}
function exactIntervalSet(def){return uniq(def.intervals.map(m12)).sort((a,b)=>a-b)}
function contrast(hex){const h=(hex||"").replace("#","");if(h.length!==6)return"#fff";const[r,g,b]=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16));return(.299*r+.587*g+.114*b)>155?"#171717":"#fff"}
