function bindModes(id,key,fn){document.querySelectorAll(`#${id} button`).forEach(b=>b.onclick=()=>{state[key]=b.dataset.mode;localStorage.setItem("ga3."+key,b.dataset.mode);syncSegment(id,b.dataset.mode,"mode");fn()})}
function syncSegment(id,value,attr="mode"){document.querySelectorAll(`#${id} button`).forEach(b=>b.classList.toggle("active",b.dataset[attr]===value))}
function screen(name){document.querySelectorAll(".screen").forEach(s=>s.classList.toggle("active",s.dataset.screen===name));document.querySelectorAll(".bottom-nav button").forEach(b=>b.classList.toggle("active",b.dataset.target===name));if(name==="library")renderLibrary();if(name==="preferences")renderPrefs();if(name==="tools")renderTools();if(name==="studio")renderStudio();window.scrollTo({top:0,behavior:"smooth"})}
function scrollRoot(id){requestAnimationFrame(()=>el(id).querySelector(".active")?.scrollIntoView({behavior:"smooth",block:"nearest",inline:"center"}))}
function shiftRoot(scope,d){const k=scope+"Root";state[k]=(state[k]+d+ROOTS.length)%ROOTS.length;if(scope==="chord")state.chordVoice=0;else state[scope+"Pos"]=0;renderScope(scope);addHistory(scope);scrollRoot(scope+"Roots")}
