function selectedVoicing(){const vs=getVoicings();return vs[state.chordVoice]||vs[0]||null}
function fingerMapForVoicing(){const v=selectedVoicing();const map=new Map();if(!v)return map;const nums=fingerNumbers(v.frets);v.frets.forEach((f,i)=>{if(f!=null)map.set(`${i}:${f}`,nums[i]||"0")});return map}
function fretboardHTML(scope,r,def,mode,win=null){const strings=tuningStrings(),set=pcsFor(r.pc,def),imap=new Map(def.intervals.map((x,i)=>[m12(x),def.labels[i]])),fingers=scope==="chord"&&mode==="fingers"?fingerMapForVoicing():null;let h=`<div class="fretboard" style="grid-template-rows:24px repeat(${strings.length},42px)"><div></div><div class="fret-no">0</div>`;for(let f=1;f<=15;f++)h+=`<div class="fret-no">${[3,5,7,9,12,15].includes(f)?f:""}</div>`;[...strings].map((s,i)=>({...s,original:i})).reverse().forEach(str=>{h+=`<div class="string-label">${str.name}</div>`;for(let f=0;f<=15;f++){const p=m12(str.pc+f),rel=m12(p-r.pc),on=set.includes(p),inside=!win||(f>=win.s&&f<=win.e);let label=mode==="notes"?nn(p,r.prefer):mode==="intervals"?(imap.get(rel)||""):"",show=on,extra=inside?"":"dimmed";if(fingers){const finger=fingers.get(`${str.original}:${f}`);show=!!finger;label=finger||"";extra=""}h+=`<div class="fret-cell ${f===0?"open-col":""}">${show?markerHTML(label,rel,extra):""}</div>`}});return h+"</div>"}
function renderChordBoard(){el("chordFretboard").innerHTML=fretboardHTML("chord",rootObj("chord"),CHORDS[state.chordType],state.chordMode)}
function renderScaleBoards(){const r=rootObj("scale"),d=SCALES[state.scaleType],w=WINDOWS[state.scalePos];el("scaleFretboard").innerHTML=fretboardHTML("scale",r,d,state.scaleMode);el("scalePositionBoard").innerHTML=fretboardHTML("scale",r,d,state.scaleMode,w);el("scalePosCounter").textContent=`${state.scalePos+1} / ${WINDOWS.length}`;el("scalePositionMeta").textContent=`${w.n} · cases ${w.s}–${w.e}`}
function renderArpBoards(){const r=rootObj("arp"),d=ARPS[state.arpType],w=WINDOWS[state.arpPos];el("arpFretboard").innerHTML=fretboardHTML("arp",r,d,state.arpMode);el("arpPositionBoard").innerHTML=fretboardHTML("arp",r,d,state.arpMode,w);el("arpPosCounter").textContent=`${state.arpPos+1} / ${WINDOWS.length}`;el("arpPositionMeta").textContent=`${w.n} · cases ${w.s}–${w.e}`}

function standardShapeVoicings(r,key){if(state.tuningId!=="standard"||tuningStrings().length!==6)return[];const out=[],sh=STANDARD_SHAPES[key]||[];sh.forEach(x=>{const openPc=x.rs===6?4:9,rf=m12(r.pc-openPc);[rf,rf+12].forEach(base=>{const f=x.f.map(v=>v==null?null:v+base),vals=f.filter(v=>v!=null);if(vals.length&&Math.max(...vals)<=15)out.push({frets:f,tag:x.tag,kind:"shape"})})});return out}
function drop2Voicings(r,key){const def=CHORDS[key],ints=exactIntervalSet(def),strings=tuningStrings();if(ints.length!==4||strings.length<4)return[];const orders=[];for(let inv=0;inv<4;inv++){const close=ints.slice(inv).concat(ints.slice(0,inv).map(x=>x+12)),dropped=[close[0],close[1],close[2]-12,close[3]].sort((a,b)=>a-b);orders.push({seq:dropped.map(m12),inv})}const out=[];for(let start=0;start<=strings.length-4;start++){const ss=[start,start+1,start+2,start+3];orders.forEach(o=>{const cand=ss.map((si,j)=>{const a=[];for(let f=0;f<=15;f++)if(m12(strings[si].pc+f-r.pc)===o.seq[j])a.push(f);return a}),valid=[];for(const a of cand[0])for(const b of cand[1])for(const c of cand[2])for(const d of cand[3]){const vals=[a,b,c,d],abs=vals.map((f,j)=>strings[ss[j]].midi+f);if(!(abs[0]<abs[1]&&abs[1]<abs[2]&&abs[2]<abs[3]))continue;if(Math.max(...vals)-Math.min(...vals)>5)continue;valid.push(vals)}valid.sort((x,y)=>Math.max(...x)-Math.max(...y)||Math.min(...x)-Math.min(...y));valid.slice(0,2).forEach(vals=>{const frets=Array(strings.length).fill(null);ss.forEach((si,j)=>frets[si]=vals[j]);out.push({frets,tag:`Drop 2 · ${["fondamentale","1er renversement","2e renversement","3e renversement"][o.inv]} · cordes ${strings.length-start}–${strings.length-start-3}`,kind:"drop2"})})})}return out}
function genericVoicings(r,key){const def=CHORDS[key],target=exactIntervalSet(def),strings=tuningStrings(),out=[];const use=Math.min(4,strings.length);for(let start=0;start<=strings.length-use;start++){for(let anchor=0;anchor<=12;anchor++){const frets=Array(strings.length).fill(null),used=new Set();let ok=true;for(let j=0;j<use;j++){const si=start+j;let best=null,bestRel=null;for(let f=Math.max(0,anchor-1);f<=Math.min(15,anchor+4);f++){const rel=m12(strings[si].pc+f-r.pc);if(target.includes(rel)&&(best==null||Math.abs(f-anchor)<Math.abs(best-anchor))){best=f;bestRel=rel}}if(best==null){ok=false;break}frets[si]=best;used.add(bestRel)}if(ok&&used.size>=Math.min(3,target.length)){out.push({frets,tag:`voicing compact · cordes ${strings.length-start}–${strings.length-start-use+1}`,kind:"generated"});break}}}return out}
function getVoicings(){const r=rootObj("chord"),key=state.chordType,out=[];if(state.tuningId==="standard"){const o=STANDARD_OPEN[`${r.label}|${key}`];if(o)out.push({frets:o,tag:"position ouverte",kind:"open"})}out.push(...standardShapeVoicings(r,key),...drop2Voicings(r,key),...genericVoicings(r,key));const seen=new Set();return out.filter(v=>{const q=v.frets.map(x=>x==null?"x":x).join("-");if(seen.has(q))return false;seen.add(q);return true}).sort((a,b)=>{const p={open:0,shape:1,drop2:2,generated:3};return(p[a.kind]??9)-(p[b.kind]??9)})}
