function renderCustomDataList(){const w=el("customDataList"),items=[...state.customChords.map(x=>({...x,kind:"chord"})),...state.customScales.map(x=>({...x,kind:"scale"}))];if(!items.length){w.innerHTML='<div class="empty-state">Aucun accord ou gamme personnalisé.</div>';return}w.innerHTML="";items.forEach(x=>{const b=document.createElement("button");b.className="library-item";b.innerHTML=`<strong>${x.def.name}</strong><small>${x.kind==="chord"?"Accord":"Gamme"} · ${x.def.labels.join(" · ")} · toucher pour supprimer</small>`;b.onclick=()=>{if(!confirm(`Supprimer « ${x.def.name} » ?`))return;if(x.kind==="chord"){state.customChords=state.customChords.filter(y=>y.key!==x.key);delete CHORDS[x.key];if(state.chordType===x.key)state.chordType="maj";save("ga3.customChords",state.customChords)}else{state.customScales=state.customScales.filter(y=>y.key!==x.key);delete SCALES[x.key];if(state.scaleType===x.key)state.scaleType="major";save("ga3.customScales",state.customScales)}buildSelects();renderAll()};w.appendChild(b)})}
