function saveCustomDefinition(){const name=el("customName").value.trim();if(!name){toast("Indique un nom");return}if(state.customIntervals.length<2){toast("Choisis au moins deux intervalles");return}const raw=el("customLabels").value.split(",").map(x=>x.trim()).filter(Boolean),labels=raw.length===state.customIntervals.length?raw:state.customIntervals.map(i=>INTERVAL_NAMES[i]),key=`custom_${Date.now()}`;if(state.customKind==="chord"){const def={name,symbol:el("customSymbol").value.trim(),intervals:[...state.customIntervals],labels,group:"Personnalisés",custom:true};CHORDS[key]=def;state.customChords.push({key,def});save("ga3.customChords",state.customChords);state.chordType=key}else{const def={name,intervals:[...state.customIntervals],labels,family:"Personnalisés",custom:true};SCALES[key]=def;state.customScales.push({key,def});save("ga3.customScales",state.customScales);state.scaleType=key}buildSelects();closeCustom();renderAll();screen(state.customKind==="chord"?"chords":"scales");toast("Ajouté")}
let audioCtx=null;function ensureAudio(){audioCtx??=new(window.AudioContext||window.webkitAudioContext)();return audioCtx}
function tone(freq,when,d=.7,g=.05,type="triangle"){const c=ensureAudio(),o=c.createOscillator(),v=c.createGain();o.type=type;o.frequency.value=freq;v.gain.setValueAtTime(.0001,when);v.gain.exponentialRampToValueAtTime(g,when+.012);v.gain.exponentialRampToValueAtTime(.0001,when+d);o.connect(v);v.connect(c.destination);o.start(when);o.stop(when+d+.03)}
